/**
 * Single source of truth for the project-local rundot folder (TS mirror of the
 * C# `Venus.RundotPaths` in `cli/venus_cli/RundotPaths.cs`).
 *
 * The canonical (visible) name is `rundot`; `.rundot` (hidden) is the legacy
 * form, still readable. Reads prefer the canonical folder and fall back to
 * legacy. Keep dir names and lookup order here only — callers must not
 * re-hardcode the literals.
 *
 * Scope: project-local config folder resolution. The user-global `~/.rundot`
 * home dir is out of scope.
 */

import { existsSync, statSync } from 'fs'
import { basename, join } from 'path'

/** Canonical (visible) project folder name. */
export const RUNDOT_CANONICAL_DIR = 'rundot'
/** Legacy (hidden) project folder name; still readable. */
export const RUNDOT_LEGACY_DIR = '.rundot'

/** Read lookup order — canonical preferred, legacy fallback. */
export const RUNDOT_LOOKUP_ORDER = [RUNDOT_CANONICAL_DIR, RUNDOT_LEGACY_DIR] as const

/** True when `p` exists and is a directory (a plain file named `rundot` doesn't count). */
function isDir(p: string): boolean {
  try {
    return statSync(p).isDirectory()
  } catch {
    return false
  }
}

/**
 * Absolute path of the rundot folder to READ from at this root: canonical if it
 * exists (as a directory), else legacy. Returns null when neither exists.
 *
 * A regular file named `rundot` is ignored so it can't shadow a legacy `.rundot/`.
 */
export function resolveRundotDir(projectRoot: string): string | null {
  for (const name of RUNDOT_LOOKUP_ORDER) {
    const candidate = join(projectRoot, name)
    if (isDir(candidate)) return candidate
  }
  return null
}

/**
 * Absolute path of the rundot folder to READ SERVER CONFIG from at this root.
 * Like `resolveRundotDir`, but skips a canonical `rundot/` that exists yet holds
 * no loadable config (no recognized server-config file and no `simulation/`
 * directory), so a populated legacy `.rundot/` is never shadowed by an empty
 * canonical folder. Returns the first candidate that holds config, the first
 * existing directory if none hold config, or null when neither exists.
 */
export function resolveRundotConfigDir(
  projectRoot: string,
  hasConfig: (dir: string) => boolean,
): string | null {
  let firstExisting: string | null = null
  for (const name of RUNDOT_LOOKUP_ORDER) {
    const candidate = join(projectRoot, name)
    if (!isDir(candidate)) continue
    if (firstExisting === null) firstExisting = candidate
    if (hasConfig(candidate)) return candidate
  }
  return firstExisting
}

/**
 * `rundot/` or `.rundot/` — the trailing-slash display prefix for a resolved
 * dir, for user-facing error messages and loaded-file lists.
 */
export function rundotDisplayPrefix(resolvedDir: string): string {
  return `${basename(resolvedDir)}/`
}
