import fs from 'fs'
import path from 'path'
import { RUNDOT_LOOKUP_ORDER } from '../rundotPaths'

/**
 * Project-root-relative path to the V2 realtime config. Prefers the canonical
 * `rundot/realtime.config.json`, falls back to legacy `.rundot/realtime.config.json`,
 * then to root `rooms.config.json`.
 */
export function resolveRoomsConfigPath(projectRoot: string): string {
  for (const dir of RUNDOT_LOOKUP_ORDER) {
    const rel = `${dir}/realtime.config.json`
    if (fs.existsSync(path.join(projectRoot, rel))) {
      return rel
    }
  }
  return 'rooms.config.json'
}
